<script setup lang="ts">import { computed, onMounted, ref } from "vue"; import { useRoute } from "vue-router"; import { ElMessage } from "element-plus"; import { get, post } from "@/api/client"; import type { Order } from "@/types"; const route = useRoute(); const order = ref<Order | null>(null); const id = computed(() => String(route.params.id)); onMounted(async () => { order.value = await get<Order>(`/purchase-orders/${id.value}`) }); async function action(name: string): Promise<void> { await post(`/purchase-orders/${id.value}/${name}`); ElMessage.success("操作成功") }</script>
<template><el-card v-if="order"><template #header>采购订单 {{ order.order_no }}</template><el-descriptions :column="2" border><el-descriptions-item label="供应商">{{ order.supplier_id }}</el-descriptions-item><el-descriptions-item label="状态">{{ order.status }}</el-descriptions-item><el-descriptions-item label="预计日期">{{ order.expected_date }}</el-descriptions-item><el-descriptions-item label="总金额">{{ order.total_amount }}</el-descriptions-item></el-descriptions><div class="actions"><el-button v-for="name in ['submit', 'approve', 'reject', 'cancel']" :key="name" @click="action(name)">{{ name === 'submit' ? '提交' : name === 'approve' ? '审批' : name === 'reject' ? '拒绝' : '取消' }}</el-button><el-button type="primary" @click="action('receive')">收货</el-button></div></el-card><el-skeleton v-else :rows="5" animated /></template>
